async function addCameraFollowFrame(){
 if(mode!=='shot'||exporting)return;stop();const scene=await getScene(currentShot());while(renderBusy)await new Promise(resolve=>setTimeout(resolve,0));if(scene.editTasks?.size)await Promise.all([...scene.editTasks]);await scene.sample(time,{editing:freeCamera,freeCamera,evaluate:true});const source=activeCameraFollow();if(!source)throw Error('当前时刻没有相机跟随片段');const pose=scene.followPose(source.clip,time);checkpoint();let track=currentShot().tracks.find(track=>track.target==='camera'&&track.property==='cameraPosition');if(!track){track=newTrack('camera','cameraPosition');currentShot().tracks.push(track);}setKey(track,time,pose.position);const key=track.keys.find(key=>Math.abs(key.time-time)<1e-5);key.follow={track:source.track.id,clip:source.clip.id};if(currentShot().inspectorDrafts)delete currentShot().inspectorDrafts[key.id];track.enabled=true;$('track-target').value='camera';targetProperties();setTimelinePicked([{kind:'key',id:key.id,track:track.id}]);changed({instances:false});
}
function cameraFollowFrameButton(){const control=button('＋ 跟随帧',addCameraFollowFrame);control.dataset.cameraAction='follow-frame';control.title='引用当前跟随片段的位置';control.disabled=mode!=='shot'||exporting||!activeCameraFollow();return control;}
function removeSelection(){const batch=selectionEntries();if(batch.length>1){removeTimelineBatch(batch);return;}if(selection?.kind==='object'&&!canEdit())return;const item=selected();if(!item)return;if(selection.kind==='track'&&item.property==='audio'){removeAudioLane(item);return;}checkpoint();if(['track','segment'].includes(selection.kind))freezeRemovedFollowKeys(new Set([selection.id]));if(selection.kind==='object'){const s=currentShot(),scene=scenes.get(shotId).scene,handle=item.tile.character?.handle;s.actors=s.actors.filter(a=>a.id!==handle);scene.runtime.selectTiles([item.tile.id]);scene.runtime.deleteSelection();s.edits=scene.runtime.captureEdits();s.edits.snapshots=s.edits.snapshots.filter(snapshot=>snapshot.id!==item.tile.id||!handle||!String(item.tile.id).startsWith('preview-character:'));for(const instance of [...s.instances])if(instance.object===item.tile.id||instance.object===handle)releaseInstance(s,instance.id);scene.refreshRecords();scene.captureDocument();}else if(selection.kind==='cut')project.clips=project.clips.filter(c=>c!==item);else if(selection.kind==='audio')project.audio=project.audio.filter(c=>c!==item);else if(selection.kind==='shot'){project.shots=project.shots.filter(s=>s!==item);project.clips=project.clips.filter(c=>c.shot!==item.id);invalidate(item.id);shotId=project.shots[0]?.id||null;}else if(selection.kind==='track'){item.keys=[];item.clips=[];delete item.needsInitialValue;}else{const t=currentTrack();t.keys=t.keys.filter(k=>k!==item);t.clips=t.clips.filter(c=>c!==item);}selection=null;changed({assets:true});renderTargets();}
function duplicateShot(){const s=currentShot();if(!s)return;checkpoint();const copy=clone(s),ids=new Map();copy.id=uid();delete copy.inspectorDrafts;delete copy.inspectorDraftTimes;copy.name+=' 副本';for(const a of copy.actors){const old=a.id;a.id=uid();ids.set(old,a.id);ids.set('preview-character:'+old,'preview-character:'+a.id);}if(copy.editorDrafts)copy.editorDrafts=Object.fromEntries(Object.entries(copy.editorDrafts).map(([object,draft])=>[ids.get(object)||object,draft]));for(const instance of copy.instances){instance.object=ids.get(instance.object)||instance.object;const old=instance.id;instance.id=uid();ids.set(old,instance.id);}for(const t of copy.tracks){const previous=t.id;t.id=uid();ids.set(previous,t.id);t.target=ids.get(t.target)||t.target;for(const k of t.keys){const previous=k.id;k.id=uid();ids.set(previous,k.id);}for(const c of t.clips){const previous=c.id;c.id=uid();ids.set(previous,c.id);if(c.object)c.object=ids.get(c.object)||c.object;if(c.target)c.target=ids.get(c.target)||c.target;for(const x of c.secondary||[])x.object=ids.get(x.object)||x.object;}}for(const track of copy.tracks)for(const key of track.keys){if(key.trajectory)key.trajectory.to=ids.get(key.trajectory.to)||key.trajectory.to;}for(const track of copy.tracks)for(const key of track.keys)if(key.follow)key.follow={track:ids.get(key.follow.track)||key.follow.track,clip:ids.get(key.follow.clip)||key.follow.clip};project.shots.push(copy);shotId=copy.id;selection={kind:'shot',id:copy.id};changed({assets:true});renderTargets();}
function duplicateSelection(){const batch=selectionEntries();if(batch.length>1)return duplicateTimelineBatch(batch);if(selection?.kind==='object'){if(!canEdit())return;copyObjects();return pasteObjects();}const item=selected();if(!item)return;if(selection.kind==='shot')return duplicateShot();checkpoint();const c=clone(item);c.id=uid();delete c.initial;if(selection.kind==='cut'){c.start=clipEnd(item);project.clips.push(c);}else if(selection.kind==='audio'){c.start=item.start+item.duration;project.audio.push(c);}else if(selection.kind==='key'){c.time=clamp(item.time+frameTime(),0,currentShot().duration);if(c.time===item.time)return;currentTrack().keys.push(c);currentTrack().keys.sort((a,b)=>a.time-b.time);}else if(selection.kind==='segment'){if(item.start+item.duration*2>currentShot().duration)throw Error('镜头剩余时长不足');c.start=item.start+item.duration;currentTrack().clips.push(c);}else return;selection.id=c.id;changed();}
function splitSelection(){
 const item=selected();if(!item)return;
 if(selection.kind==='cut'){if(time<=item.start||time>=clipEnd(item))return;checkpoint();const next=splitClip(project,item.id,time);if(next){selection.id=next.id;changed();}return;}
 if(!['segment','audio'].includes(selection.kind))return;const track=currentTrack(),end=item.start+item.duration+(selection.kind==='segment'?segmentContinuation(track,item,currentShot().duration):0);if(time<=item.start+1e-6||time>=end-1e-6)return;
 checkpoint();const phaseTrack=['animation','expression','sub'].includes(track?.property),rate=phaseTrack?(item.speed||1):1,c={...clone(item),id:uid(),start:time,duration:end-time};if(c.in!==undefined||phaseTrack)c.in=(item.in||0)+(time-item.start)*rate;if(selection.kind==='audio'||track?.property==='audio'){c.audioEnvelope=sliceAudioEnvelope(item,time-item.start);item.audioEnvelope=sliceAudioEnvelope(item);}delete item.initial;delete c.initial;item.duration=time-item.start;if(selection.kind==='audio')project.audio.push(c);else{track.clips.push(c);for(const target of currentShot().tracks)for(const key of target.keys)if(key.follow?.clip===item.id&&key.time>=time)key.follow.clip=c.id;}selection.id=c.id;changed();
}
async function timelineK(){
 const batch=selectionEntries();if(batch.length>1){splitTimelineBatch(batch);return;}
 if(mode==='project'){if(!['cut','audio'].includes(selection?.kind)){const clip=activeClips(project,time).at(-1);if(!clip)return;selection={kind:'cut',id:clip.id};}splitSelection();return;}
 let track=currentTrack();if(!track)track=chosenTrack();if(!track)return;
 if(track.type==='key'){selection={kind:'track',id:track.id};insertKey();return;}
 const clip=selection?.kind==='segment'&&selection.track===track.id?selected():sampledSegments(track,time).at(-1);if(clip){selection={kind:'segment',id:clip.id,track:track.id};splitSelection();}
}

async function pasteObjects(){
 if(!canEdit())throw Error('请先退出摄像头预览');const clipboard=GTBridge.clipboard.read();if(!clipboard)throw Error('请先复制物件或人物');if(!currentShot())addShot();const scene=await getScene(currentShot());checkpoint();await scene.runtime.pasteSelection(clipboard);scene.refreshRecords();scene.captureDocument();renderDirty=true;changed({assets:tab==='objects'});renderInspector();
}
