async function restoreHistory(from,to){if(!from.length||historyBusy)return;stop();historyBusy=true;try{while(renderBusy)await new Promise(resolve=>setTimeout(resolve,0));to.push(clone(project));project=from.pop();if(!project.shots.some(s=>s.id===shotId))shotId=project.shots[0]?.id||null;selection=null;for(const [id,entry] of scenes){const shot=project.shots.find(s=>s.id===id);if(shot&&entry.scene.canRestore(shot))await entry.scene.restoreDocument(shot);else invalidate(id);}time=clamp(time,0,duration());save();projectOptions();renderAll();}finally{historyBusy=false;}}
$('undo').onclick=run(()=>restoreHistory(undo,redo));$('redo').onclick=run(()=>restoreHistory(redo,undo));
