$('export-video').onclick=()=>{stop();const f=$('export-form');exportShotId=mode==='shot'?shotId:null;f.querySelector('h2').textContent=exportShotId?'导出镜头 · '+currentShot().name:'导出项目 MP4';for(const key of ['width','height','fps'])f.elements[key].value=project[key];f.elements.bitrate.value=project.bitrate/1e6;$('export-dialog').showModal();};$('close-export').onclick=()=>$('export-dialog').close();$('cancel-export').onclick=()=>exportAbort?.abort();
$('export-form').onsubmit=run(async e=>{e.preventDefault();const f=e.currentTarget,p=exportScope(project,exportShotId);for(const key of ['width','height','fps'])p[key]=Number(f.elements[key].value);p.bitrate=Number(f.elements.bitrate.value)*1e6;validateProject(p);checkpoint();Object.assign(project,{width:p.width,height:p.height,fps:p.fps,bitrate:p.bitrate});await save();$('export-dialog').close();exporting=true;document.body.classList.add('exporting');exportAbort=new AbortController();$('progress').hidden=$('cancel-export').hidden=false;const previousMode=mode;mode='project';try{while(renderBusy)await new Promise(resolve=>setTimeout(resolve,20));const blob=await exportProject(p,{signal:exportAbort.signal,onProgress:value=>{$('progress').value=value;status('导出 '+Math.round(value*100)+'%');},getFrame:(ctx,t,w,h)=>compose(ctx,t,w,h,{output:true,source:p})});download(blob,(exportShotId?p.name.replace(/[\\/:*?"<>|]/g,'_'):filename())+'.mp4');status('已导出 MP4');}catch(error){status(error.name==='AbortError'?'已取消导出':error.message,error.name!=='AbortError');}finally{mode=previousMode;for(const [id,entry] of scenes){const shot=project.shots.find(shot=>shot.id===id);if(shot){entry.scene.shot=shot;entry.scene.evaluationDirty=true;}}exporting=false;exportAbort=null;document.body.classList.remove('exporting');$('progress').hidden=$('cancel-export').hidden=true;renderDirty=true;fitPicture();}});

window.addEventListener('keydown',e=>{if(e.target.closest('input,select,textarea,[contenteditable]')||$('export-dialog').open||exporting||!project)return;if(e.isComposing||e.defaultPrevented)return;const command=e.ctrlKey||e.metaKey,key=e.key.toLowerCase();if(command&&key==='a'&&(e.target.closest('#timeline')||timelinePicked.size)){e.preventDefault();const entries=visibleTimelineEntries();setTimelinePicked(entries);renderTimeline();renderInspector();syncControls();}else if(e.code==='Space'){e.preventDefault();run(play)();}else if(!command&&!e.altKey&&key==='k'&&!e.repeat){e.preventDefault();run(timelineK)();}else if(command&&key==='z'){e.preventDefault();run(()=>restoreHistory(e.shiftKey?redo:undo,e.shiftKey?undo:redo))();}else if(command&&key==='s'){e.preventDefault();save();}else if(command&&key==='d'){e.preventDefault();run(duplicateSelection)();}else if(key==='delete'||key==='backspace'){e.preventDefault();removeSelection();}else if(key==='arrowleft'||key==='arrowright'){e.preventDefault();seek(time+(key==='arrowleft'?-1:1)*frameTime());}else if(!command&&canEdit()&&{q:'select',w:'translate',e:'rotate',r:'scale'}[key]){e.preventDefault();setTransform({q:'select',w:'translate',e:'rotate',r:'scale'}[key]);}else if(command&&key==='c'&&selectionEntries().some(entry=>['key','segment'].includes(entry.kind))){e.preventDefault();copyTimelineSelection();}else if(command&&key==='v'&&timelineClipboard&&mode==='shot'){e.preventDefault();run(pasteTimelineSelection)();}else if(command&&canEdit()&&key==='c'){e.preventDefault();run(copyObjects)();}else if(command&&canEdit()&&key==='v'){e.preventDefault();run(pasteObjects)();}else if(key==='escape'){selection=null;renderAll();}});
