async function boot(){try{try{timelineSnap=localStorage.getItem('gtvideo.timeline-snap')!=='false';$('timeline-snap').checked=timelineSnap;autoKey=localStorage.getItem('gtvideo.auto-key')==='true';$('auto-key').checked=autoKey;}catch{}localProjects=await projects.list();if(!localProjects.length){const p=newProject();await projects.save(p);localProjects.push(p);}let last;try{last=localStorage.getItem('gtvideo.last');}catch{}await useProject(localProjects.find(p=>p.id===last)||localProjects[0]);requestAnimationFrame(tick);}catch(e){status('项目读取失败：'+e.message,true);}}
